    rewardChoice: true,
    rewardGold: REWARD_GOLD,
    rewardItems: [
      { itemId: "bow_mirror", count: 1 },
      { itemId: "tool_hatchet", count: 1 },
      { itemId: "potion_vigor", count: 1 },
