      player: playerId,
      giver: priestId,
      target: priestId,
    }, {}, { node: "offer" });
  }

  if (barkeepId > 0 && findQuestEntity(world, STARTER_RAT_QUEST_ID, playerId) <= 0) {
    lastId = instantiateQuest(world, STARTER_RAT_QUEST_ID, {
      player: playerId,
      giver: barkeepId,
      target: barkeepId,
    }, {}, { node: "offer" });
  }

  return lastId;
}

